/// FSRS-6 scheduler: a faithful port of py-fsrs 6.3.2 (open-spaced-repetition)
/// with fuzzing removed, so the same log always yields the same states.
///
/// Why a port and not `package:fsrs`: the pub.dev package (2.0.1) ships older
/// FSRS-6 default parameters and rounds with Dart semantics (half away from
/// zero) instead of Python's banker's rounding, so it does not reproduce the
/// py-fsrs reference values. The math is ~150 lines; owning it keeps the
/// scheduler deterministic and testable against `test/fixtures/fsrs_vectors.json`
/// (generated by `tool/fsrs_reference/gen_fsrs_vectors.py`).
///
/// Pure Dart.
library;

import 'dart:math' as math;

import '../../core/interfaces/progress_store.dart';
import '../../core/models/progress.dart';

/// FSRS-6 default parameters (py-fsrs 6.3.2 `DEFAULT_PARAMETERS`).
const List<double> kFsrsDefaultParameters = [
  0.212, 1.2931, 2.3065, 8.2956, 6.4133, 0.8334, 3.0194, 0.001, 1.8722, //
  0.1666, 0.796, 1.4835, 0.0614, 0.2629, 1.6483, 0.6014, 1.8729, 0.5425, //
  0.0912, 0.0658, 0.1542,
];

const double kFsrsStabilityMin = 0.001;
const double _minDifficulty = 1.0;
const double _maxDifficulty = 10.0;
const int _msPerDay = 86400000;

/// Configuration of the scheduler. The defaults are the app's fixed settings.
class FsrsConfig {
  const FsrsConfig({
    this.parameters = kFsrsDefaultParameters,
    this.desiredRetention = 0.9,
    this.learningSteps = const [Duration(minutes: 1), Duration(minutes: 10)],
    this.relearningSteps = const [Duration(minutes: 10)],
    this.maximumInterval = 36500,
  });

  final List<double> parameters;
  final double desiredRetention;
  final List<Duration> learningSteps;
  final List<Duration> relearningSteps;

  /// Days.
  final int maximumInterval;
}

/// Deterministic FSRS-6 implementation of [Scheduler].
///
/// Mapping to py-fsrs: `previous == null` is a fresh `Card()` (Learning, step 0,
/// no stability/difficulty). [FacetState.reps] counts reviews and
/// [FacetState.lapses] counts Again ratings given while in the review phase
/// (py-fsrs 6 doesn't track these; they're derived the Anki way).
class FsrsScheduler implements Scheduler {
  FsrsScheduler([this.config = const FsrsConfig()])
      : assert(config.parameters.length == 21, 'FSRS-6 needs 21 parameters'),
        _w = config.parameters,
        _decay = -config.parameters[20],
        _factor = math.pow(0.9, 1 / -config.parameters[20]).toDouble() - 1;

  final FsrsConfig config;
  final List<double> _w;
  final double _decay;
  final double _factor;

  // ------------------------------------------------------------ public API

  @override
  double retrievability(FacetState? state, DateTime now) {
    if (state == null) return 0;
    return _retrievability(state.stability, state.lastReview, now);
  }

  @override
  FacetState review(String facetId, FacetState? previous, Rating rating, DateTime now) {
    final at = now.toUtc();
    final phase = previous?.phase ?? CardPhase.learning;
    int? step = previous == null ? 0 : previous.step;
    double? s = previous?.stability;
    double? d = previous?.difficulty;
    final last = previous?.lastReview;
    final int? daysSince = last == null ? null : _floorDays(at, last);

    CardPhase newPhase = phase;
    Duration interval;

    switch (phase) {
      case CardPhase.learning:
        if (s == null || d == null) {
          s = _initialStability(rating);
          d = _clampDifficulty(_initialDifficulty(rating));
        } else if (daysSince != null && daysSince < 1) {
          s = _shortTermStability(s, rating);
          d = _nextDifficulty(d, rating);
        } else {
          s = _nextStability(d, s, _retrievability(s, last!, at), rating);
          d = _nextDifficulty(d, rating);
        }
        final steps = config.learningSteps;
        step ??= 0;
        if (steps.isEmpty || (step >= steps.length && rating != Rating.again)) {
          newPhase = CardPhase.review;
          step = null;
          interval = _days(_nextInterval(s));
        } else {
          (newPhase, step, interval) = _stepped(steps, step, rating, s, CardPhase.learning);
        }

      case CardPhase.review:
        // A review-phase state always has stability, difficulty and lastReview.
        s = s!;
        d = d!;
        if (daysSince != null && daysSince < 1) {
          s = _shortTermStability(s, rating);
        } else {
          s = _nextStability(d, s, _retrievability(s, last!, at), rating);
        }
        d = _nextDifficulty(d, rating);
        if (rating == Rating.again) {
          if (config.relearningSteps.isEmpty) {
            interval = _days(_nextInterval(s));
          } else {
            newPhase = CardPhase.relearning;
            step = 0;
            interval = config.relearningSteps[0];
          }
        } else {
          interval = _days(_nextInterval(s));
        }

      case CardPhase.relearning:
        s = s!;
        d = d!;
        if (daysSince != null && daysSince < 1) {
          s = _shortTermStability(s, rating);
          d = _nextDifficulty(d, rating);
        } else {
          s = _nextStability(d, s, _retrievability(s, last!, at), rating);
          d = _nextDifficulty(d, rating);
        }
        final steps = config.relearningSteps;
        step ??= 0;
        if (steps.isEmpty || (step >= steps.length && rating != Rating.again)) {
          newPhase = CardPhase.review;
          step = null;
          interval = _days(_nextInterval(s));
        } else {
          (newPhase, step, interval) = _stepped(steps, step, rating, s, CardPhase.relearning);
        }
    }

    final lapse = phase == CardPhase.review && rating == Rating.again;
    return FacetState(
      facetId: facetId,
      stability: s,
      difficulty: d,
      due: at.add(interval),
      lastReview: at,
      reps: (previous?.reps ?? 0) + 1,
      lapses: (previous?.lapses ?? 0) + (lapse ? 1 : 0),
      phase: newPhase,
      step: newPhase == CardPhase.review ? null : step,
    );
  }

  /// Interval in whole days that FSRS would schedule for [stability] (exposed for UI/debug).
  int nextIntervalDays(double stability) => _nextInterval(stability);

  // ------------------------------------------------------------ internals

  /// Learning/relearning step logic shared by both phases (py-fsrs `match rating`).
  (CardPhase, int?, Duration) _stepped(
    List<Duration> steps,
    int step,
    Rating rating,
    double s,
    CardPhase stayPhase,
  ) {
    switch (rating) {
      case Rating.again:
        return (stayPhase, 0, steps[0]);
      case Rating.hard:
        final Duration ivl;
        if (step == 0 && steps.length == 1) {
          ivl = _scale(steps[0], 1.5);
        } else if (step == 0 && steps.length >= 2) {
          ivl = _scale(steps[0] + steps[1], 0.5);
        } else {
          ivl = steps[step];
        }
        return (stayPhase, step, ivl);
      case Rating.good:
        if (step + 1 == steps.length) {
          return (CardPhase.review, null, _days(_nextInterval(s)));
        }
        return (stayPhase, step + 1, steps[step + 1]);
      case Rating.easy:
        return (CardPhase.review, null, _days(_nextInterval(s)));
    }
  }

  double _retrievability(double stability, DateTime lastReview, DateTime now) {
    final elapsed = math.max(0, _floorDays(now.toUtc(), lastReview));
    return math.pow(1 + _factor * elapsed / stability, _decay).toDouble();
  }

  double _clampDifficulty(double d) => d.clamp(_minDifficulty, _maxDifficulty).toDouble();

  double _clampStability(double s) => math.max(s, kFsrsStabilityMin);

  double _initialStability(Rating r) => _clampStability(_w[r.value - 1]);

  double _initialDifficulty(Rating r) => _w[4] - _ePow(_w[5] * (r.value - 1)) + 1;

  int _nextInterval(double stability) {
    final raw =
        (stability / _factor) * (math.pow(config.desiredRetention, 1 / _decay).toDouble() - 1);
    var ivl = roundHalfEven(raw);
    ivl = math.max(ivl, 1);
    ivl = math.min(ivl, config.maximumInterval);
    return ivl;
  }

  double _shortTermStability(double stability, Rating r) {
    var inc = _ePow(_w[17] * (r.value - 3 + _w[18])) * math.pow(stability, -_w[19]).toDouble();
    if (r != Rating.again) inc = math.max(inc, 1.0);
    return _clampStability(stability * inc);
  }

  double _nextDifficulty(double difficulty, Rating r) {
    final arg1 = _initialDifficulty(Rating.easy);
    final delta = -(_w[6] * (r.value - 3));
    final arg2 = difficulty + (10.0 - difficulty) * delta / 9.0;
    final next = _w[7] * arg1 + (1 - _w[7]) * arg2;
    return _clampDifficulty(next);
  }

  double _nextStability(double d, double s, double r, Rating rating) {
    final next = rating == Rating.again
        ? _nextForgetStability(d, s, r)
        : _nextRecallStability(d, s, r, rating);
    return _clampStability(next);
  }

  double _nextForgetStability(double d, double s, double r) {
    final longTerm = _w[11] *
        math.pow(d, -_w[12]).toDouble() *
        (math.pow(s + 1, _w[13]).toDouble() - 1) *
        _ePow((1 - r) * _w[14]);
    final shortTerm = s / _ePow(_w[17] * _w[18]);
    return math.min(longTerm, shortTerm);
  }

  double _nextRecallStability(double d, double s, double r, Rating rating) {
    final hardPenalty = rating == Rating.hard ? _w[15] : 1.0;
    final easyBonus = rating == Rating.easy ? _w[16] : 1.0;
    return s *
        (1 +
            _ePow(_w[8]) *
                (11 - d) *
                math.pow(s, -_w[9]).toDouble() *
                (_ePow((1 - r) * _w[10]) - 1) *
                hardPenalty *
                easyBonus);
  }
}

/// Python's `round()` for a float: round half to even.
int roundHalfEven(double x) {
  final f = x.floorToDouble();
  final diff = x - f;
  if (diff < 0.5) return f.toInt();
  if (diff > 0.5) return f.toInt() + 1;
  final fi = f.toInt();
  return fi.isEven ? fi : fi + 1;
}

/// Python's `timedelta.days` for `a - b`: whole days, floored.
int _floorDays(DateTime a, DateTime b) {
  final us = a.microsecondsSinceEpoch - b.microsecondsSinceEpoch;
  const usPerDay = _msPerDay * 1000;
  final q = us ~/ usPerDay;
  return (us % usPerDay != 0 && us < 0) ? q - 1 : q;
}

/// `math.e ** x` exactly as Python computes it (C `pow`, not `exp`), so values
/// match py-fsrs bit for bit as often as possible.
double _ePow(double x) => math.pow(math.e, x).toDouble();

Duration _days(int days) => Duration(milliseconds: days * _msPerDay);

/// `timedelta * factor` (py rounds to whole microseconds, half to even).
Duration _scale(Duration d, double factor) =>
    Duration(microseconds: roundHalfEven(d.inMicroseconds * factor));
